#include "common/benchmark.hpp"
#include "cfd/multibody/system.hpp"
#include <cmath>
int main(int argc,char**argv){using namespace cfd::examples;const auto o=parse_options(argc,argv);const std::size_t count=o.quick?20U:180U*o.scale,steps=o.quick?20U:600U;Timer setup;cfd::multibody::DemConfig cfg;cfg.dt=2e-5;cfg.contact.normal_stiffness=2e5;cfg.contact.normal_damping=80;cfg.contact.friction=0.4;cfd::multibody::ExplicitDemSystem dem(cfg);dem.add_plane({{0,1,0},0});const std::size_t cols=10U;for(std::size_t i=0;i<count;++i){const double x=(double(i%cols)-4.5)*0.022,y=0.12+double(i/cols)*0.021;dem.add_particle({x,y,0},0.01,2500.0);}const double setup_ms=setup.milliseconds();Timer sim;dem.run(steps);const double sim_ms=sim.milliseconds();double checksum=0;for(const auto&b:dem.bodies())checksum+=b.state.position.y+b.state.linear_velocity.y;emit({"phase13_multibody_dem","granular_settling","cpu","particle_steps",count,steps,setup_ms,sim_ms,double(count)*double(steps),checksum});return 0;}
